insert into public.legislacao_artigos
    (referencia, texto, vigencia_de, vigencia_ate, id_materia, id_topico)
values
    ('Decreto nº 12.341/2024 — art. 2º (Princípios gerais do uso da força)',
     'Art. 2º São princípios gerais de uso da força em segurança pública: I - a legalidade; II - a precaução; III - a necessidade; IV - a proporcionalidade; V - a razoabilidade; VI - a responsabilização; e VII - a não discriminação.',
     '2024-12-24', null, 16, 223),
    ('Decreto nº 12.341/2024 — art. 6º, I–V (Diretrizes de implementação)',
     'Art. 6º Para implementação do disposto na Lei nº 13.060, de 22 de dezembro de 2014, e neste Decreto, os órgãos de segurança pública deverão observar as seguintes diretrizes: I - elaboração e atualização de atos normativos que disciplinem o uso diferenciado da força, inclusive de instrumentos de menor potencial ofensivo; II - registro e publicação de dados sobre o uso da força; III - disponibilização de equipamento de proteção individual e de, no mínimo, dois instrumentos de menor potencial ofensivo a todo profissional de segurança pública em serviço; IV - instituição de programas continuados de atenção à saúde mental dos profissionais de segurança pública que se envolvam em ocorrências de alto risco; V - implementação, monitoramento e avaliação de ações relacionadas ao uso diferenciado da força, que incluam diagnósticos, padronização de procedimentos e aquisições, entre outros aspectos.',
     '2024-12-24', null, 16, 223),
    ('Decreto nº 12.341/2024 — art. 6º, VI–X (Diretrizes de implementação)',
     'Art. 6º Para implementação do disposto na Lei nº 13.060, de 22 de dezembro de 2014, e neste Decreto, os órgãos de segurança pública deverão observar as seguintes diretrizes: VI - implementação de ações para a redução da vitimização dos profissionais de segurança pública e da letalidade policial; VII - capacitação sobre o uso diferenciado da força; VIII - fomento a pesquisas e estudos sobre o uso da força, com ênfase na avaliação de impacto; IX - normatização e fiscalização da identificação dos profissionais de segurança pública, de forma a possibilitar a individualização de suas ações durante o serviço; e X - normatização da atuação dos profissionais de segurança pública em situações que envolvam gerenciamento de crises, busca pessoal, busca domiciliar, uso de algemas e providências a serem adotadas nos casos em que o uso da força resultar em lesão corporal ou morte.',
     '2024-12-24', null, 16, 223),
    ('Decreto nº 12.341/2024 — art. 7º (Controle e monitoramento do uso da força)',
     'Art. 7º São diretrizes para atuação dos mecanismos de fiscalização e de controle interno dos órgãos de segurança pública na supervisão do uso da força: I - garantia da transparência e do acesso público a dados e informações sobre o uso da força; II - disponibilização de canais de denúncia e orientações de registro e acompanhamento de reclamações sobre o uso da força, nos meios de comunicação oficiais, de forma clara e acessível; III - garantia do processamento eficaz e transparente das reclamações sobre o uso da força; e IV - fortalecimento da atuação das corregedorias e ouvidorias dos órgãos de segurança pública.',
     '2024-12-24', null, 16, 223),
    ('Lei nº 13.060/2014 — arts. 2º e 4º (Prioridade e definição de instrumentos)',
     'Art. 2º Os órgãos de segurança pública deverão priorizar a utilização dos instrumentos de menor potencial ofensivo, desde que o seu uso não coloque em risco a integridade física ou psíquica dos policiais, e deverão obedecer aos seguintes princípios: I - legalidade; II - necessidade; III - razoabilidade e proporcionalidade. Parágrafo único. Não é legítimo o uso de arma de fogo: I - contra pessoa em fuga que esteja desarmada ou que não represente risco imediato de morte ou de lesão aos agentes de segurança pública ou a terceiros; e II - contra veículo que desrespeite bloqueio policial em via pública, exceto quando o ato represente risco de morte ou lesão aos agentes de segurança pública ou a terceiros. Art. 4º Para os efeitos desta Lei, consideram-se instrumentos de menor potencial ofensivo aqueles projetados especificamente para, com baixa probabilidade de causar mortes ou lesões permanentes, conter, debilitar ou incapacitar temporariamente pessoas.',
     '2014-12-23', null, 16, 223),
    ('Lei nº 12.830/2013 — art. 2º, §§ 1º, 2º e 4º a 6º (Investigação pelo delegado)',
     'Art. 2º As funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia são de natureza jurídica, essenciais e exclusivas de Estado. § 1º Ao delegado de polícia, na qualidade de autoridade policial, cabe a condução da investigação criminal por meio de inquérito policial ou outro procedimento previsto em lei, que tem como objetivo a apuração das circunstâncias, da materialidade e da autoria das infrações penais. § 2º Durante a investigação criminal, cabe ao delegado de polícia a requisição de perícia, informações, documentos e dados que interessem à apuração dos fatos. § 4º O inquérito policial ou outro procedimento previsto em lei em curso somente poderá ser avocado ou redistribuído por superior hierárquico, mediante despacho fundamentado, por motivo de interesse público ou nas hipóteses de inobservância dos procedimentos previstos em regulamento da corporação que prejudique a eficácia da investigação. § 5º A remoção do delegado de polícia dar-se-á somente por ato fundamentado. § 6º O indiciamento, privativo do delegado de polícia, dar-se-á por ato fundamentado, mediante análise técnico-jurídica do fato, que deverá indicar a autoria, materialidade e suas circunstâncias.',
     '2013-06-21', null, 13, 99),
    ('Lei nº 12.594/2012 — arts. 52–54 (Definição, elaboração e conteúdo do PIA)',
     'Art. 52. O cumprimento das medidas socioeducativas, em regime de prestação de serviços à comunidade, liberdade assistida, semiliberdade ou internação, dependerá de Plano Individual de Atendimento (PIA), instrumento de previsão, registro e gestão das atividades a serem desenvolvidas com o adolescente. Parágrafo único. O PIA deverá contemplar a participação dos pais ou responsáveis, os quais têm o dever de contribuir com o processo ressocializador do adolescente, sendo esses passíveis de responsabilização administrativa, nos termos do art. 249 da Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente), civil e criminal. Art. 53. O PIA será elaborado sob a responsabilidade da equipe técnica do respectivo programa de atendimento, com a participação efetiva do adolescente e de sua família, representada por seus pais ou responsável. Art. 54. Constarão do plano individual, no mínimo: I - os resultados da avaliação interdisciplinar; II - os objetivos declarados pelo adolescente; III - a previsão de suas atividades de integração social e/ou capacitação profissional; IV - atividades de integração e apoio à família; V - formas de participação da família para efetivo cumprimento do plano individual; e VI - as medidas específicas de atenção à sua saúde.',
     '2012-04-18', null, 60, 472),
    ('Lei nº 12.594/2012 — arts. 55–56 (PIA: conteúdo adicional e prazos)',
     'Art. 55. Para o cumprimento das medidas de semiliberdade ou de internação, o plano individual conterá, ainda: I - a designação do programa de atendimento mais adequado para o cumprimento da medida; II - a definição das atividades internas e externas, individuais ou coletivas, das quais o adolescente poderá participar; e III - a fixação das metas para o alcance de desenvolvimento de atividades externas. Parágrafo único. O PIA será elaborado no prazo de até 45 (quarenta e cinco) dias da data do ingresso do adolescente no programa de atendimento. Art. 56. Para o cumprimento das medidas de prestação de serviços à comunidade e de liberdade assistida, o PIA será elaborado no prazo de até 15 (quinze) dias do ingresso do adolescente no programa de atendimento.',
     '2012-04-18', null, 60, 472),
    ('Decreto nº 7.892/2013 — art. 2º, II (Ata de Registro de Preços; redação histórica)',
     'Art. 2º Para os efeitos deste Decreto, são adotadas as seguintes definições: II - ata de registro de preços - documento vinculativo, obrigacional, com característica de compromisso para futura contratação, em que se registram os preços, fornecedores, órgãos participantes e condições a serem praticadas, conforme as disposições contidas no instrumento convocatório e propostas apresentadas.',
     '2013-02-23', '2023-12-30', 14, 95),
    ('Lei nº 8.625/1993 — art. 26, IV (Requisição de diligências investigatórias)',
     'Art. 26. No exercício de suas funções, o Ministério Público poderá: IV - requisitar diligências investigatórias e a instauração de inquérito policial e de inquérito policial militar, observado o disposto no art. 129, inciso VIII, da Constituição Federal, podendo acompanhá-los.',
     '1993-02-15', null, 16, 223),
    ('Lei nº 14.113/2020 — art. 3º, III (IPVA na composição do Fundeb)',
     'Art. 3º Os Fundos, no âmbito de cada Estado e do Distrito Federal, são compostos por 20% (vinte por cento) das seguintes fontes de receita: III - Imposto sobre a Propriedade de Veículos Automotores (IPVA) previsto no inciso III do caput do art. 155 da Constituição Federal.',
     '2020-12-25', null, 17, 451),
    ('Lei nº 13.964/2019 — art. 5º (Alteração do rol de crimes hediondos)',
     'Art. 5º O art. 1º da Lei nº 8.072, de 25 de julho de 1990, passa a vigorar com as seguintes alterações: “I - homicídio (art. 121), quando praticado em atividade típica de grupo de extermínio, ainda que cometido por um só agente, e homicídio qualificado (art. 121, § 2º, incisos I, II, III, IV, V, VI, VII e VIII);” “Parágrafo único. Consideram-se também hediondos, tentados ou consumados: I - o crime de genocídio, previsto nos arts. 1º, 2º e 3º da Lei nº 2.889, de 1º de outubro de 1956; II - o crime de posse ou porte ilegal de arma de fogo de uso proibido, previsto no art. 16 da Lei nº 10.826, de 22 de dezembro de 2003; III - o crime de comércio ilegal de armas de fogo, previsto no art. 17 da Lei nº 10.826, de 22 de dezembro de 2003; IV - o crime de tráfico internacional de arma de fogo, acessório ou munição, previsto no art. 18 da Lei nº 10.826, de 22 de dezembro de 2003; V - o crime de organização criminosa, quando direcionado à prática de crime hediondo ou equiparado.”',
     '2020-01-23', null, 19, 90),
    ('CPP — art. 492, I, e, §§ 3º e 4º (Execução provisória no Tribunal do Júri)',
     'Art. 492. Em seguida, o presidente proferirá sentença que: I - no caso de condenação: e) mandará o acusado recolher-se ou recomendá-lo-á à prisão em que se encontra, se presentes os requisitos da prisão preventiva, ou, no caso de condenação a uma pena igual ou superior a 15 (quinze) anos de reclusão, determinará a execução provisória das penas, com expedição do mandado de prisão, se for o caso, sem prejuízo do conhecimento de recursos que vierem a ser interpostos. § 3º O presidente poderá, excepcionalmente, deixar de autorizar a execução provisória das penas de que trata a alínea e do inciso I do caput deste artigo, se houver questão substancial cuja resolução pelo tribunal ao qual competir o julgamento possa plausivelmente levar à revisão da condenação. § 4º A apelação interposta contra decisão condenatória do Tribunal do Júri a uma pena igual ou superior a 15 (quinze) anos de reclusão não terá efeito suspensivo.',
     '2020-01-23', null, 13, 153),
    ('Lei nº 14.230/2021 — art. 2º (Dolo na Lei de Improbidade Administrativa)',
     'Art. 2º A Lei nº 8.429, de 2 de junho de 1992, passa a vigorar com as seguintes alterações: “Art. 1º O sistema de responsabilização por atos de improbidade administrativa tutelará a probidade na organização do Estado e no exercício de suas funções, como forma de assegurar a integridade do patrimônio público e social, nos termos desta Lei. Parágrafo único. (Revogado). § 1º Consideram-se atos de improbidade administrativa as condutas dolosas tipificadas nos arts. 9º, 10 e 11 desta Lei, ressalvados tipos previstos em leis especiais. § 2º Considera-se dolo a vontade livre e consciente de alcançar o resultado ilícito tipificado nos arts. 9º, 10 e 11 desta Lei, não bastando a voluntariedade do agente. § 3º O mero exercício da função ou desempenho de competências públicas, sem comprovação de ato doloso com fim ilícito, afasta a responsabilidade por ato de improbidade administrativa. § 4º Aplicam-se ao sistema da improbidade disciplinado nesta Lei os princípios constitucionais do direito administrativo sancionador.”',
     '2021-10-26', null, 14, 66)
on conflict (referencia) do update set
    texto = excluded.texto,
    vigencia_de = excluded.vigencia_de,
    vigencia_ate = excluded.vigencia_ate,
    id_materia = excluded.id_materia,
    id_topico = excluded.id_topico;
